    h, w = len(grid), len(grid[0])
    output = [[0]*w for _ in range(h)]

    # Cell (r,c) becomes:
    # - 9 if it's within 1 cell of a 9 in input
    # - 1 if it's within 1 to 2 cells of a 9, not 9
    # - 5 otherwise

    for r in range(h):
        for c in range(w):
            min_dist = float('inf')
            for dr in range(h):
                for dc in range(w):
                    if grid[dr][dc] == 9:
                        # Chebyshev distance (king's move)
                        dist = max(abs(r-dr), abs(c-dc))
                        min_dist = min(min_dist, dist)

            if min_dist == 0:
                output[r][c] = 9
            elif min_dist == 1:
                output[r][c] = 9  # Adjacent to 9
            elif min_dist == 2:
                output[r][c] = 1  # Within 2 but not 1
            else:
                output[r][c] = 5

    return output

